<?php
declare(strict_types=1);
return static function(PDO $db):void{$db->exec('CREATE TABLE IF NOT EXISTS media_posters (id INTEGER PRIMARY KEY AUTOINCREMENT, video_asset_id INTEGER NOT NULL, video_version_id INTEGER NOT NULL, poster_uuid TEXT NOT NULL UNIQUE, timestamp_seconds REAL NOT NULL, source_width INTEGER NOT NULL, source_height INTEGER NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(video_asset_id) REFERENCES media_assets(id), FOREIGN KEY(video_version_id) REFERENCES media_versions(id)); CREATE TABLE IF NOT EXISTS media_poster_variants (id INTEGER PRIMARY KEY AUTOINCREMENT, poster_id INTEGER NOT NULL, variant_key TEXT NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, format TEXT NOT NULL, mime_type TEXT NOT NULL, path TEXT NOT NULL UNIQUE, size_bytes INTEGER NOT NULL, checksum TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(poster_id,variant_key,format), FOREIGN KEY(poster_id) REFERENCES media_posters(id)); CREATE INDEX IF NOT EXISTS idx_media_posters_version ON media_posters(video_version_id); CREATE INDEX IF NOT EXISTS idx_media_poster_variants_poster ON media_poster_variants(poster_id);');};
